// Parse Articles: turns the pasted table (copied from Excel / Google Sheets / CSV) into Elasticsearch documents.
const form = $('Article Form').first().json;
const cfg = $('Settings').first().json;
const text = String(form['Articles'] ?? '').replace(/^\uFEFF/, '');
const fail = (message) => [{ json: { ok: false, title: 'Nothing was loaded', message } }];

const firstLine = text.split(/\r?\n/)[0] || '';
const count = (c) => firstLine.split(c).length - 1;
const delim = count('\t') > 0 ? '\t' : count(';') > count(',') ? ';' : ',';

// small CSV/TSV reader that understands "quoted, cells" and multi-line cells
const rows = [];
let row = [], cell = '', quoted = false;
for (let i = 0; i < text.length; i++) {
  const ch = text[i];
  if (quoted) {
    if (ch === '"') { if (text[i + 1] === '"') { cell += '"'; i++; } else quoted = false; }
    else cell += ch;
  } else if (ch === '"' && cell === '') quoted = true;
  else if (ch === delim) { row.push(cell); cell = ''; }
  else if (ch === '\n' || ch === '\r') {
    if (ch === '\r' && text[i + 1] === '\n') i++;
    row.push(cell); cell = '';
    if (row.some((c) => c.trim() !== '')) rows.push(row);
    row = [];
  } else cell += ch;
}
row.push(cell);
if (row.some((c) => c.trim() !== '')) rows.push(row);

if (rows.length < 2) return fail('I found no articles. Paste the header row (title, content, url, category, tags) plus at least one article row.');

const header = rows[0].map((h) => h.trim().toLowerCase());
const find = (names) => header.findIndex((h) => names.includes(h));
const col = {
  title: find(['title', 'question', 'name']),
  content: find(['content', 'answer', 'text', 'body']),
  url: find(['url', 'link']),
  category: find(['category']),
  tags: find(['tags', 'keywords']),
};
if (col.title < 0 || col.content < 0) return fail('The first row must contain the column names "title" and "content" (you can also use "question" and "answer").');

const get = (r, i) => (i >= 0 && r[i] !== undefined ? String(r[i]).replace(/\s+/g, ' ').trim() : '');
const now = new Date().toISOString();
const lines = [];
let loaded = 0, skipped = 0;
for (const r of rows.slice(1)) {
  const title = get(r, col.title).slice(0, 300);
  const content = get(r, col.content).slice(0, 20000);
  if (!title || !content) { skipped++; continue; }
  if (loaded >= 500) { skipped++; continue; }
  const doc = { title, content, updated_at: now };
  const url = get(r, col.url);
  if (/^https?:\/\//i.test(url)) doc.url = url;
  const category = get(r, col.category);
  if (category) doc.category = category;
  const tags = get(r, col.tags);
  if (tags) doc.tags = tags;
  lines.push(JSON.stringify({ index: {} }), JSON.stringify(doc));
  loaded++;
}
if (!loaded) return fail('Every row was missing a title or content, so nothing was loaded.');

const base = String(cfg.esUrl || '').trim().replace(/\/+$/, '');
const index = String(cfg.esIndex || 'support-kb').trim();
return [{ json: {
  ok: true,
  removeFirst: String(form['Remove existing articles first?'] || 'No').toLowerCase() === 'yes',
  loaded, skipped,
  bulkUrl: `${base}/${index}/_bulk?refresh=true`,
  deleteUrl: `${base}/${index}/_delete_by_query?refresh=true&conflicts=proceed`,
  bulkBody: lines.join('\n') + '\n',
} }];

// Check Result: tells the person clearly whether the upload worked.
const p = $('Parse Articles').first().json;
const res = $input.first().json || {};
if (res.error || res.errors === true || !Array.isArray(res.items)) {
  const items = Array.isArray(res.items) ? res.items : [];
  const bad = items.find((i) => i.index && i.index.error);
  const why = bad ? (bad.index.error.reason || bad.index.error.type) : (typeof res.error === 'string' ? res.error : 'Elasticsearch did not accept the articles.');
  return [{ json: { title: 'Upload failed', message: 'Elasticsearch said: ' + why + '. Check that Docker and Elasticsearch are running and that the address in the Settings node is right.' } }];
}
const ok = res.items.filter((i) => i.index && i.index.status >= 200 && i.index.status < 300).length;
const extra = p.skipped ? ` ${p.skipped} row(s) were skipped (missing title or content).` : '';
return [{ json: { title: 'Done!', message: `${ok} article(s) are now in your bot's library.${extra} Ask the chatbot a question about them to test.` } }];
